CREATE TABLE `industry_service_relations` (`industry_id` INT NOT NULL, `service_id` INT NOT NULL, PRIMARY KEY (`industry_id`,`service_id`), CONSTRAINT `industry_service_relations_industry_id_fkey` FOREIGN KEY (`industry_id`) REFERENCES `industries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, CONSTRAINT `industry_service_relations_service_id_fkey` FOREIGN KEY (`service_id`) REFERENCES `services` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;